{"packet_id":"D034-01","doc_id":"D034","jurisdiction":"Hoboken, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Hoboken mandatory disclosures for rent increases over 10%","requirement":"A residential landlord raising rent more than 10% on renewal of a lease with a current tenant must give an itemized cost breakdown, a statement whether a rent algorithm was used, notice of the right to sue, and Division of Housing contact information.","key_value":"10%","coverage_conditions":"All residential landlords increasing rent by more than 10% upon renewal of a lease with a current tenant year over year.","applicability":{"conditions":[],"per_tenancy":"Rent increase of more than 10% upon renewal of a lease with a current tenant year over year","coverage_quotes":["All residential landlords seeking to increase rent by more than 10% upon a renewal of a lease with a current tenant year over year shall be required to make the following disclosures to existing tenants either in the lease upon renewal (must be clearly indicated on the first page) or on a form provided by the Hoboken Division of Housing prior to the increase being implemented:"]},"exemptions":null,"penalty":"A landlord who pleads guilty to or is found guilty of failing to give the disclosures is subject to a fine not exceeding $1,000 per incident.","effective_date":null,"valid_through":null,"citation":"Hoboken Mun. Code § 158-1","quoted_span":"All residential landlords seeking to increase rent by more than 10% upon a renewal of a lease with a current tenant year over year shall be required to make the following disclosures to existing tenants either in the lease upon renewal (must be clearly indicated on the first page) or on a form provided by the Hoboken Division of Housing prior to the increase being implemented:","interaction":null,"relations":[],"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D034-01","doc_id":"D034","jurisdiction":"Hoboken, NJ","category":"algorithmic_rent_setting","lifecycle":"enacted","title":"Hoboken prohibition on algorithmic rent fixing","requirement":"Landlords renting residential dwelling units in Hoboken may not price fix using algorithmic pricing: software, algorithms, or data-sharing platforms that collect and analyze nonpublic competitor information to coordinate, recommend, or implement rents, lease terms or occupancy.","key_value":null,"coverage_conditions":"Landlords who rent any residential dwelling unit in the City of Hoboken; a dwelling unit is any primary residence, excluding medical/long-term care or detention facilities.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":["Landlords who rent any residential dwelling unit (defined as any primary residence excluding medical/long-term care or detention facilities) in the City of Hoboken are prohibited from price fixing using algorithmic pricing."]},"exemptions":null,"penalty":"Upon conviction, penalties prescribed under N.J.S.A. 40:49-5, or a fine not exceeding $2,000, or community service not exceeding 90 days.","effective_date":null,"valid_through":null,"citation":"Hoboken Mun. Code § 158-2","quoted_span":"For purposes of this chapter, \"price fixing using algorithmic pricing\" shall be defined as the use of software, algorithms, or data-sharing platforms to collect and analyze nonpublic competitor information from other real estate lessors in order to coordinate, recommend, or implement rental prices, lease terms, or occupancy levels for residential dwelling units among competing real estate lessors.","interaction":null,"relations":[],"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D034-01","n_rules":2,"note":null}

